from typing import List
import heapq

class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)
        changeIndices = [x - 1 for x in changeIndices]  # Convert to 0-indexed

        # Check if it's possible to mark all indices by the given second
        def is_possible(second):
            marked = [False] * n
            remaining = nums[:]
            actions = []
            for i in range(second - 1, -1, -1):
                idx = changeIndices[i]
                if not marked[idx]:
                    if remaining[idx] == 0:
                        marked[idx] = True
                        actions.append((i, 'mark', idx))
                    else:
                        actions.append((i, 'decrement', idx))
                        remaining[idx] -= 1
                else:
                    actions.append((i, 'decrement', idx))
                    remaining[idx] -= 1

            # Check if all indices are marked
            return all(marked)

        # Binary search for the earliest second
        left, right = 1, m
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if is_possible(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result
